{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE hox_db.maplemonk.DOH_AND_DRR_DATA AS With retailez_quantity as ( SELECT \"PRODUCT_NAME\" AS \"PRODUCT_NAME\", SUM(NET_QUANTITY) AS \"Net Quantity\", ROUND( ( SUM( CASE WHEN REPORT_DATE BETWEEN CURRENT_DATE - INTERVAL \'7 DAY\' AND CURRENT_DATE THEN NET_QUANTITY END ) / 7.00 ), 0 ) AS \"Avg 7 day Net Quantity\", ROUND( ( SUM( CASE WHEN REPORT_DATE BETWEEN CURRENT_DATE - INTERVAL \'30 DAY\' AND CURRENT_DATE THEN NET_QUANTITY END ) / 30.00 ), 0 ) AS \"Avg 30 day Net Quantity\" FROM maplemonk.hox_yfl_7chef_secondary_tax_summary WHERE \"REPORT_DATE\" < CAST(DATEADD(day,1,CURRENT_DATE()) AS DATE) AND ( LOWER(MARKETPLACE) = \'retailez secondary\' ) AND ( NOT REPORT_TYPE IS NULL AND NOT REFERENCE_CODE IS NULL ) GROUP BY \"PRODUCT_NAME\" ORDER BY \"Net Quantity\" DESC LIMIT 10000 ), shopify_quantity as ( SELECT \"PRODUCT_NAME\" AS \"PRODUCT_NAME\", SUM(NET_QUANTITY) AS \"Net Quantity\", ROUND( ( SUM( CASE WHEN REPORT_DATE BETWEEN CURRENT_DATE - INTERVAL \'7 DAY\' AND CURRENT_DATE THEN NET_QUANTITY END ) / 7.00 ), 0 ) AS \"Avg 7 day Net Quantity\", ROUND( ( SUM( CASE WHEN REPORT_DATE BETWEEN CURRENT_DATE - INTERVAL \'30 DAY\' AND CURRENT_DATE THEN NET_QUANTITY END ) / 30.00 ), 0 ) AS \"Avg 30 day Net Quantity\" FROM maplemonk.hox_yfl_7chef_secondary_tax_summary WHERE \"REPORT_DATE\" < CAST(DATEADD(day,1,CURRENT_DATE()) AS DATE) AND ( LOWER(MARKETPLACE) LIKE ANY (\'%shopify%\', \'%spare parts%\') ) AND ( NOT REPORT_TYPE IS NULL AND NOT REFERENCE_CODE IS NULL ) GROUP BY \"PRODUCT_NAME\" ORDER BY \"Net Quantity\" DESC LIMIT 10000 ), DRR as ( SELECT a.product_name, a.\"Avg 7 day Net Quantity\" as shopify_7_day_drr, a.\"Avg 30 day Net Quantity\" as shopify_30_day_drr, b.\"Avg 7 day Net Quantity\" as retailez_7_day_drr, b.\"Avg 30 day Net Quantity\" as retailez_30_day_drr FROM shopify_quantity a JOIN retailez_quantity b on a.product_name = b.product_name ) SELECT CASE WHEN c.\"SKU Name\" = \'Curaa Electric Pepper Grinder Black\' THEN \'Curaa Electric Pepper Mill\' ELSE c.\"SKU Name\" END AS \"SKU Name\", c.\"ASIN \", c.origin, c.\"Head/Tail\", c.\"Lot Size\", c.\"Lead Time\", c.\"WH Inventory\", c.\"RetailEZ Inventory\", d.shopify_7_day_drr, d.shopify_30_day_drr, d.retailez_7_day_drr, d.retailez_30_day_drr, ROUND( ifnull( c.\"WH Inventory\"/nullifzero(d.shopify_7_day_drr),null),0 ) AS shopify_7_day_doh, ROUND( ifnull( c.\"WH Inventory\"/nullifzero(d.shopify_30_day_drr),null),0 ) AS shopify_30_day_doh, CASE WHEN c.\"RetailEZ Inventory\" = \'N/A\' THEN null ELSE ROUND( ifnull( c.\"RetailEZ Inventory\"/nullifzero(d.retailez_7_day_drr),null),0 ) END AS retailez_7_day_doh, CASE WHEN c.\"RetailEZ Inventory\" = \'N/A\' THEN null ELSE ROUND( ifnull( c.\"RetailEZ Inventory\"/nullifzero(d.retailez_30_day_drr),null),0 ) END AS retailez_30_day_doh FROM hox_db.maplemonk.inventory_google_sheets_final_sheet c LEFT JOIN DRR d ON ( CASE WHEN c.\"SKU Name\" = \'Curaa Electric Pepper Grinder Black\' THEN \'Curaa Electric Pepper Mill\' ELSE c.\"SKU Name\" END ) = d.PRODUCT_NAME;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            